return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-10-01T08:25:56+00:00','po-revision-date'=>'2026-10-01T08:25:56+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'Prodajite Zinn Digital® hosting sa svoje vlastite WordPress stranice — WordPress, WooCommerce, agencijski, reseller, cloud i VPS hosting. Pretražujte i nudite domene sa svog reseller računa, prijavite svoje klijente izravno u njihovu administratorsku ploču za hosting i automatski uspostavite hosting kada je WooCommerce narudžba plaćena.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'Platforma za hosting odgovorila je sa statusom %d.','Find your domain name'=>'Pronađite naziv svoje domene','Search'=>'Pretraži','No extensions were checked for that name.'=>'Za taj naziv nije označena nijedna ekstenzija.','Domain search is unavailable on this site at the moment.'=>'Pretraživanje domena trenutno nije dostupno na ovoj stranici.','We could not reach the domain registry just now. Please try again in a moment.'=>'Trenutno nismo mogli uspostaviti vezu s registrom domena. Molimo pokušajte ponovno za trenutak.','The API key is missing or no longer valid. Check it under Zinn Digital® → Reseller Toolkit.'=>'API ključ nedostaje ili više nije važeći. Provjerite ga pod Zinn Digital® → Reseller Toolkit.','This API key does not carry the sites.view permission, which the domain search needs. Add it to the key in your reseller panel, or clear the key here to fall back to the public search.'=>'Ovaj API ključ nema dozvolu sites.view koja je potrebna za pretraživanje domena. Dodajte je u ključ na svojoj resellerskoj ploči ili ovdje izbrišite ključ kako biste se vratili na javno pretraživanje.','Only administrators see this:'=>'Samo administratori ovo vide:','We could not check this one — try again'=>'Nismo mogli provjeriti ovu stavku — pokušajte ponovno','Already registered'=>'Već registrirano','Available — ask us for a price'=>'Dostupno — pitajte nas za cijenu','Available — %1$s %2$s for the first year'=>'Dostupno — %1$s %2$s za prvu godinu','Register it'=>'Registriraj ga','Manage my hosting'=>'Upravljanje mojim hostingom','Please sign in first.'=>'Molimo vas da se najprije prijavite.','This account is not linked to a hosting service yet.'=>'Ovaj račun još nije povezan s uslugom hostinga.','The hosting platform did not return a sign-in link.'=>'Platforma za hosting nije vratila vezu za prijavu.','Reseller Toolkit'=>'Alatni okvir za preprodavače','Account'=>'Korisnički račun','Features'=>'Značajke','Styling'=>'Stilski dizajn','AI agents (MCP)'=>'AI agenti (MCP)','Allow AI agents (MCP)'=>'Dopusti AI agentima (MCP)','Off: the tools below and their REST routes are not registered at all.'=>'Isključeno: alati u nastavku i njihove REST rute uopće nisu registrirani.','Your Zinn Digital® reseller account'=>'Vaš resellerski račun za Zinn Digital®','Create a reseller API key in your Zinn® dashboard under Developer → API keys, and paste it here.'=>'Izradite API ključ za preprodavače na svojoj Zinn® upravljačkoj ploči pod Developer → API keys i zalijepite ga ovdje.','Reseller API key'=>'API ključ za preprodavače','Held on this site only, and never included in an export or a diagnostics report.'=>'Pohranjeno samo na ovoj web-lokaciji i nikada nije uključeno u izvoz ili izvješće o dijagnostici.','Plan to provision'=>'Plan za dodjelu resursa','The plan code new customers are put on. Leave blank to be asked each time.'=>'Kod plana na koji se stavljaju novi korisnici. Ostavite prazno da se pita svaki put.','API address'=>'API adresa','Leave this alone unless Zinn® support has asked you to change it.'=>'Ovo nemojte mijenjati osim ako vas podrška za Zinn® nije zatražila da to promijenite.','Control-panel address'=>'Adresa upravljačke ploče','Where the “My hosting” link sends your customers.'=>'Kamo poveznica „Moje udomljavanje” šalje vaše klijente.','Domain search'=>'Pretraga domena','Provide the [zinn_domain_search] shortcode'=>'Unesite kratki kôd [zinn_domain_search]','Put the shortcode on any page to let visitors check a domain and buy it through you.'=>'Postavite kratki kod na bilo koju stranicu kako biste omogućili posjetiteljima provjeru domene i kupnju putem vas.','Panel link'=>'Veza s upravljačkom pločom','Show a “My hosting” link to signed-in customers'=>'Prikaži vezu „Moje hosting usluge” prijavljenim korisnicima','WooCommerce provisioning'=>'Instalacija WooCommerce','Provision hosting automatically when a WooCommerce order completes'=>'Automatski kreirajte hosting kada se WooCommerce narudžba dovrši','Only takes effect on orders containing a product you have mapped to a Zinn® plan.'=>'Primjenjuje se samo na narudžbe koje sadrže proizvod koji ste povezali sa Zinn® paketom.','Domain search appearance'=>'Izgled pretraživanja domene','This widget renders inside your own theme. Pick a preset, or set your own colours — either way nothing is added to your pages that a visitor can see as ours.'=>'Ovaj se widget prikazuje unutar vaše vlastite teme. Odaberite predložak ili postavite vlastite boje — u svakom slučaju, vašim se stranicama ne dodaje ništa što posjetitelj može vidjeti kao naše.','Every class the widget uses is listed in the plugin’s readme, so a developer can override anything a preset does not cover.'=>'Svaka klasa koju widget koristi navedena je u datoteci readme dodatka, tako da programer može nadjačati sve što unaprijed postavljena postavka ne obuhvaća.','Follow my theme'=>'Slijedi moju temu','Soft'=>'Meko','High contrast'=>'Visoki kontrast','Compact'=>'Kompaktno','Buy-link colour'=>'Boja veze za kupnju','“Available” colour'=>'Boja za „Dostupno”','“Could not check” colour'=>'Boja za „Nije moguće provjeriti”','Error colour'=>'Boja pogreške','Corner rounding'=>'Zaobljenje kutova','Space inside each row'=>'Prostor unutar svakog retka','Text size'=>'Veličina teksta','Domain-name weight'=>'Težina naziva domene','No reseller API key yet.'=>'Još nema API ključa za preprodavače.','Domain search already works without one, at the public prices. The panel link and WooCommerce provisioning need a key: create one in your Zinn® dashboard under Developer → API keys.'=>'Pretraga domena već radi bez njega, po javnim cijenama. Vezi upravljačke ploče i WooCommerce provizioniranju potreban je ključ: izradite ga na svojoj Zinn® upravljačkoj ploči pod Razvojni programeri → API ključevi.','Open my Zinn® dashboard'=>'Otvorite moju Zinn® upravljačku ploču','A key is set, but nothing is switched on.'=>'Ključ je postavljen, ali ništa nije uključeno.','None of the three features is enabled, so this plugin is doing nothing on your site. Turn on what you need under Features.'=>'Nijedna od tri značajke nije omogućena, tako da ovaj dodatak ne radi ništa na vašoj stranici. Uključite ono što vam treba pod Značajke.','Open Features'=>'Otvori značajke','Ready — %d feature switched on.'=>'Spremno — %d značajka uključena.' . "\0" . 'Spremno — %d značajki je uključeno.' . "\0" . 'Spremno — %d značajki je uključeno.','Selling from'=>'Prodaje od','Settings'=>'Postavke','No API key yet, so nothing is connected.'=>'Još nema API ključa, pa ništa nije povezano.','Not connected: %s'=>'Nije povezano: %s','Connected. Your reseller programme is %s.'=>'Povezano. Vaš resellerski program je %s.','No Zinn® API key is configured, so nothing was provisioned.'=>'Nije konfiguriran nikakav Zinn® API ključ, tako da ništa nije dodijeljeno.','This order did not include a domain name, so there was nothing to provision.'=>'Ova narudžba nije uključivala naziv domene, tako da nije bilo ničega za rezervirati.','The hosting platform did not return a site.'=>'Platforma za hosting nije vratila web-mjesto.','Zinn® hosting provisioned for %1$s (service %2$s).'=>'Zinn® hosting pripremljen za %1$s (usluga %2$s).','The hosting platform did not return a client account.'=>'Platforma za hosting nije vratila klijentski račun.','Zinn® hosting was NOT provisioned: %s'=>'Zinn® hosting nije isporučen: %s','Zinn® product line'=>'Zinn® linija proizvoda','The Zinn® product line to provision when this product is bought. Leave blank to use the default from the plugin settings.'=>'Linija proizvoda Zinn® za isporuku prilikom kupnje ovog proizvoda. Ostavite prazno za korištenje zadane vrijednosti iz postavki dodatka.','Zinn® hosting'=>'Zinn® hosting','Service id'=>'ID usluge','Nothing provisioned for this order.'=>'Ništa nije osigurano za ovu narudžbu.','Stored. Type a new value to replace it.'=>'Spremljeno. Upišite novu vrijednost da biste je zamijenili.','Filter this list…'=>'Filtriraj ovaj popis…','Filter this list'=>'Filtriraj ovaj popis','Nothing matches that filter.'=>'Nijedna stavka ne odgovara tom filteru.','Add a row'=>'Dodaj redak','Remove this row'=>'Ukloni ovaj redak','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Copied'=>'Kopirano','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® priključak na ovoj stranici i radi li on.','No connection is needed for this plugin.'=>'Za ovaj dodatak nije potrebna nikakva veza.','Open settings'=>'Otvori postavke','You do not have permission to change these settings.'=>'Nemate dopuštenje za promjenu ovih postavki.','Settings sections'=>'Odjeljci postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvoz postavki','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća svaku postavku ovog dodatka na zadane vrijednosti. Nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezi datoteku s postavkama','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokene ili API ključeve – morat ćete ih ponovno unijeti na novoj web-lokaciji.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Sve postavke na ovom dodatku vraćene su na zadane vrijednosti.','Done.'=>'Gotovo.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Ta se datoteka nije mogła pročitati. Odaberite datoteku postavki izvezenu iz Zinn® dodatka.','That file is too large to be a settings export.'=>'Ta je datoteka prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz postavki za Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta je datoteka izvezena iz drugog dodatka (%s), pa bi njen uvoz ovdje pohranio postavke koje ovaj dodatak ne prepoznaje.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'Uvezen je %d postavk. Zaporke i API ključevi se nikada ne izvoze, stoga ih unesite ponovno.' . "\0" . '%d postavki je uvezeno. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih ponovo unesite.' . "\0" . '%d postavki je uvezeno. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih ponovo unesite.','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pažnju','Not connected'=>'Nije spojeno','Running on your own account'=>'Pokretanje na vašem računu','We could not check this'=>'Nismo mogli ovo provjeriti','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostičko izvješće i mi ćemo ga pregledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Posljednja provjera prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošalji ovo u Zinn® podršku','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Upravo je to ono što će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu uključeni.','The diagnostics report that will be sent'=>'Dijagnostičko izvješće koje će biti poslano','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće Zinn® podršci','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvaramo vam zahtjev za podršku i odgovaramo e-poštom. Ako ga radije ne biste poslali, kopirajte ga iznad i sami ga zalijepite u zahtjev.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo mogli dosegnuti Zinn Digital® s ovog poslužitelja (%s). Umjesto toga kopirajte gore navedeno izvješće i otvorite zahtjev — s vašim postavkama nije ništa u redu.','Sent. Zinn® support has your report and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće i odgovorit će vam putem e-pošte.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće — referenca %s — i odgovorit će vam putem e-pošte.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko izvješća u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno – prethodna su stigla.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutno nije mogao prihvatiti izvješće — problem je s naše strane, ne s vaše. Pokušajte ponovno uskoro ili kopirajte gornje izvješće u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvještaj je odbijen (HTTP %d). Kopirajte ga gore i otvorite tiket, navodeći taj broj.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje vode više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite već uspostavljene stranice, domene i plasmane poveznica, pri čemu se novac sigurno čuva dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude kojima je to struka','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih radnika: pregledajte više od 10.000 gotovih usluga pisaca, dizajnerâ, programera i SEO stručnjaka ili objavite projekt i dopustite im da licitiraju.','Style preset'=>'Prezadani stil','A starting point. Anything below overrides it.'=>'Polazna točka. Sve ispod toga ima prednost.','Use my own colours and sizes'=>'Koristi moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Ostavite ovo isključeno i unaprijed postavljena vrijednost koristit će se točno takva kakva jest.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja Zinn® nije izdala vezu za preuzimanje za ovo ažuriranje. Provjerite može li ova web-lokacija pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti s usluge ažuriranja za Zinn® (%s). Pokušajte ponovno za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.','The action could not be completed. Try again, and if it keeps failing, contact the site administrator.'=>'Radnja se nije mogla dovršiti. Pokušajte ponovno, a ako i dalje ne uspijeva, obratite se administratoru web-mjesta.','A required value is missing or has the wrong form. Check the ability\'s input schema.'=>'Nedostaje obavezna vrijednost ili je u pogrešnom obliku. Provjerite ulaznu shemu funkcije.','The site refused the request.'=>'Web-mjesto je odbilo zahtjev.','Let AI assistants such as Claude, Cursor or VS Code work on this site for you through MCP (Model Context Protocol). They sign in as a WordPress user with an application password and can do only what that user is allowed to do.'=>'Neka AI asistenti kao što su Claude, Cursor ili VS Code rade na ovoj web-lokaciji umjesto vas putem MCP-a (Model Context Protocol). Oni se prijavljuju kao WordPress korisnik s lozinkom aplikacije i mogu učiniti samo ono što je tom korisniku dopušteno.','AI agents need WordPress 6.9 or later. Update WordPress to use them.'=>'AI agenti zahtijevaju WordPress 6.9 ili noviju verziju. Ažurirajte WordPress kako biste ih mogli koristiti.','Connection address (MCP endpoint)'=>'Adresa povezivanja (MCP krajnja točka)','Create an application password for your user'=>'Stvorite aplikacijsku lozinku za svog korisnika','Add this to your AI app’s MCP settings, with your username and that password:'=>'Dodajte ovo u MCP postavke svoje AI aplikacije, zajedno sa svojim korisničkim imenom i tom lozinkom:','VS Code: put the same entry under "servers" in .vscode/mcp.json, not under "mcpServers".'=>'VS Code: stavite isti unos pod "servers" u .vscode/mcp.json, a ne pod "mcpServers".','Tools an AI agent can use here (%d):'=>'Alati koje AI agent ovdje može koristiti (%d):','User guide: AI agents and MCP'=>'Korisnički vodič: AI agenti i MCP','Developer docs: abilities, REST and MCP'=>'Razvojna dokumentacija: mogućnosti, REST i MCP','Manage your hosting clients, their plans and their sites on Zinn Digital® from this site.'=>'Upravljajte svojim klijentima hostinga, njihovim paketima i web-mjestima na platformi Zinn Digital® s ove lokacije.','Your clients, their plans and their sites, through your Zinn Digital® reseller account.'=>'Vaši klijenti, njihovi paketi i njihove web-lokacije, putem vašeg posredničkog računa za Zinn Digital®.','Read your reseller account'=>'Pročitajte svoj resellerski račun','Returns your reseller account in one read: brand, plans, clients and services counts, and what is set up.'=>'Vraća vaš preprodavački račun u jednom čitanju: brend, planove, broj klijenata i usluga te ono što je postavljeno.','List your clients'=>'Prikaz popisa klijenata','Lists your client accounts, a page at a time (cursor, limit).'=>'Prikazuje vaše klijentske račune, stranicu po stranicu (cursor, limit).','Create a client'=>'Kreiraj klijenta','Creates a client account under yours (name; default_currency, a three-letter code). Put them on a plan before their first site.'=>'Stvara klijentski račun pod vašim (ime; default_currency, troznamenkasti kod). Dodijelite im paket prije njihove prve web-lokacije.','Read a client\'s plan'=>'Pročitajte plan klijenta','Returns which plan a client is on and what it costs you (client_id).'=>'Vraća na kojem je paketu klijent i koliko vas to košta (client_id).','Put a client on a plan'=>'Dodijelite klijentu paket','Puts a client on one of your plans (client_id, plan_code; interval: month or year). Do this before their first site.'=>'Stavlja klijenta na jedan od vaših paketa (client_id, plan_code; interval: mjesec ili godina). Učinite to prije njihove prve stranice.','List the plans you can sell'=>'Prikažite planove koje možete prodavati','Lists the hosting plans and their prices (product_line and currency narrow it).'=>'Navodi planove hostinga i njihove cijene (product_line i currency ih sužavaju).','List your clients\' sites'=>'Popisite stranice svojih klijenata','Lists everything you have provisioned for your clients (client_id and status narrow it), a page at a time.'=>'Navodi sve što ste osigurali za svoje klijente (client_id i status sužavaju pretragu), stranicu po stranicu.','Create a site for a client'=>'Kreirajte web-mjesto za klijenta','Creates a hosted site for one of your clients (client_id, product_line, primary_domain). It is billed to your account at the client\'s plan, as from your shop.'=>'Stvara hostanu stranicu za jednog od vaših klijenata (client_id, product_line, primary_domain). Naplaćuje se vašem računu prema planu klijenta, kao iz vaše trgovine.','Suspend a client\'s site'=>'Suspendiraj klijentovu stranicu','Puts a client\'s site on a non-payment hold (site_id; reason: your own note, never shown to the client). The site stops serving until it is unsuspended.'=>'Stavlja klijentovu web-lokaciju u status mirovanja zbog neplaćanja (site_id; razlog: vaša vlastita bilješka, koja se nikada ne prikazuje klijentu). Web-lokacija prestaje s radom dok se ponovno ne aktivira.','Unsuspend a client\'s site'=>'Aktiviraj klijentovu stranicu','Lifts a non-payment hold, so the site serves again (site_id).'=>'Uklanja blokadu zbog neplaćanja, tako da web-mjesto ponovno radi (site_id).','Read the Reseller Toolkit settings'=>'Pročitajte postavke alata za preprodavače','Returns this plugin\'s settings (the API address, the plan new orders use, which features are on). The API key is never returned, only whether one is saved.'=>'Vraća postavke ovog dodatka (API adresu, paket koji koriste nove narudžbe, koje su značajke uključene). API ključ se nikada ne vraća, već samo informacija je li spremljen.','Change the Reseller Toolkit settings'=>'Promijenite postavke alata za preprodavače','Changes the settings you send (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce) and keeps the rest. The API key and address are changed on the screen only.'=>'Mijenja postavke koje šaljete (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce), a ostale zadržava. API ključ i adresa mijenjaju se samo na zaslonu.','Add your Zinn Digital® reseller API key on the Reseller Toolkit screen first.'=>'Prvo dodajte svoj API ključ preprodavača za Zinn Digital® na zaslonu Alata za preprodavače.']];